/// Whether reading `property` on the built-in global object `object` is side-effect free.
#[rustfmt::skip]
fn is_known_global_object_property(object: &str, property: &str) -> bool {
    match object {
        "Math" => matches!(property, "PI" | "E" | "abs" | "floor" | "random"),
        "Object" => matches!(property, "keys" | "create" | "assign" | "prototype"),
        "Reflect" => matches!(property, "apply" | "get"),
        "Symbol" => matches!(property, "iterator" | "asyncIterator"),
        "JSON" => matches!(property, "parse" | "stringify"),
        "console" => matches!(property, "log" | "error" | "warn"),
        _ => false,
    }
}

/// Known `Object.prototype` methods that are side-effect free to access.
fn is_object_prototype_property(property: &str) -> bool {
    matches!(
        property,
